STAMP="$(date +%Y%m%d-%H%M%S)-$$"
for TOOL in python3 tar sha256sum base64 mktemp; do
  command -v "$TOOL" >/dev/null || { echo "Chybí nástroj: $TOOL"; exit 1; }
done
